import java.io.InputStream; import java.io.IOException; import java.io.BufferedWriter; import java.io.FileWriter; import java.io.OutputStreamWriter; import java.util.Arrays; public class Solution { static class FastScanner { private InputStream stream; private byte[] buf = new byte[1024 * 64]; private int head = 0, tail = 0; public FastScanner(InputStream stream) { this.stream = stream; } private int read() { if (head >= tail) { head = 0; try { tail = stream.read(buf, 0, buf.length); } catch (IOException e) { tail = -1; } if (tail <= 0) return -1; } return buf[head++]; } public int nextInt() { int c = read(); while (c <= 32) { if (c == -1) return -1; c = read(); } int res = 0; while (c > 32) { if (c < '0' || c > '9') break; res = res * 10 + c - '0'; c = read(); } return res; } } public static void main(String[] args) throws IOException { FastScanner scanner = new FastScanner(System.in); int t = scanner.nextInt(); if (t == -1) return; String outputPath = System.getenv("OUTPUT_PATH"); BufferedWriter bw; if (outputPath != null && !outputPath.trim().isEmpty()) { bw = new BufferedWriter(new FileWriter(outputPath)); } else { bw = new BufferedWriter(new OutputStreamWriter(System.out)); } for (int tItr = 0; tItr < t; tItr++) { int n = scanner.nextInt(); int m = scanner.nextInt(); int[] headAdj = new int[n + 1]; Arrays.fill(headAdj, -1); int[] toAdj = new int[2 * m]; int[] nextAdj = new int[2 * m]; int edgeCount = 0; for (int i = 0; i < m; i++) { int u = scanner.nextInt(); int v = scanner.nextInt(); toAdj[edgeCount] = v; nextAdj[edgeCount] = headAdj[u]; headAdj[u] = edgeCount++; toAdj[edgeCount] = u; nextAdj[edgeCount] = headAdj[v]; headAdj[v] = edgeCount++; } int s = scanner.nextInt(); int[] dist = new int[n + 1]; Arrays.fill(dist, -1); boolean[] isNeighbor = new boolean[n + 1]; int[] prev = new int[n + 2]; int[] next = new int[n + 2]; for (int i = 1; i <= n; i++) { prev[i] = i - 1; next[i] = i + 1; } next[0] = 1; prev[n + 1] = n; int[] q = new int[n + 5]; int headQ = 0, tailQ = 0; dist[s] = 0; q[tailQ++] = s; int p = prev[s], nxt = next[s]; next[p] = nxt; prev[nxt] = p; while (headQ < tailQ) { int u = q[headQ++]; for (int e = headAdj[u]; e != -1; e = nextAdj[e]) { isNeighbor[toAdj[e]] = true; } int curr = next[0]; while (curr != n + 1) { if (!isNeighbor[curr]) { dist[curr] = dist[u] + 1; q[tailQ++] = curr; int pCurr = prev[curr], nCurr = next[curr]; next[pCurr] = nCurr; prev[nCurr] = pCurr; curr = pCurr; } curr = next[curr]; } for (int e = headAdj[u]; e != -1; e = nextAdj[e]) { isNeighbor[toAdj[e]] = false; } } boolean first = true; for (int i = 1; i <= n; i++) { if (i == s) continue; if (!first) bw.write(" "); bw.write(String.valueOf(dist[i])); first = false; } bw.newLine(); } bw.flush(); bw.close(); } }